build_bowtie2_index.run:
try:
    shell("""
        source /etc/profile.d/modules.sh
        module load bowtie2
        mkdir -p {params.idx_dir}
        bowtie2-build {input.fasta} {params.idx_dir}/reference_index --threads {threads}
        touch {output.done}
    """)
except Exception as e:
    update_step_status(EXP_ID, "processing", "failed")
    raise e

remove_rrna.shell:
source /etc/profile.d/modules.sh
        module load bowtie2

  mkdir -p run_output/rrna/{wildcards.sample}; bowtie2 -x {params.index_prefix} -1 {input.r1} -2 {input.r2} --no-unal --omit-sec-seq --threads {threads} --mm --seed 1337 --time --un-conc-gz run_output/rrna/{wildcards.sample}_no_rRNA.fastq.gz 2> run_output/rrna/{wildcards.sample}_no_rRNA.log; touch {output.done}

star_align.shell:
source /etc/profile.d/modules.sh
       module load star
mkdir -p run_output/alignment/{wildcards.sample}; STAR --runThreadN {threads} --genomeDir {input.index} --readFilesIn {input.r1} {input.r2} --readFilesCommand gunzip -c --outFileNamePrefix run_output/alignment/{wildcards.sample}/{wildcards.sample}_ --quantMode GeneCounts --twopassMode Basic; touch {output.done}
